import 'package:flutter/material.dart';import 'package:flutter/services.dart';class HomeScreen extends StatefulWidget {  const HomeScreen({super.key});  @override  State<HomeScreen> createState() => _HomeScreenState();}class _HomeScreenState extends State<HomeScreen> {  bool _copied = false;  static const String _flutterCode = """import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({super.key});  @override  Widget build(BuildContext context) {    return MaterialApp(      title: 'Hello World',      theme: ThemeData(        colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),        useMaterial3: true,      ),      home: const Scaffold(        body: Center(          child: Text(            'Hello, World!',            style: TextStyle(fontSize: 24),          ),        ),      ),    );  }""";  void _copyToClipboard() {    Clipboard.setData(const ClipboardData(text: _flutterCode));    setState(() {      _copied = true;    });    Future.delayed(const Duration(seconds: 2), () {      if (mounted) {        setState(() {          _copied = false;        });      }    });  }  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: Colors.grey[50],      body: Center(        child: SingleChildScrollView(          padding: const EdgeInsets.all(16.0),          child: Container(            constraints: const BoxConstraints(maxWidth: 768.0),            width: double.infinity,            decoration: BoxDecoration(              color: Colors.white,              borderRadius: BorderRadius.circular(16.0),              boxShadow: [                BoxShadow(                  color: Colors.black.withOpacity(0.1),                  blurRadius: 10,                  offset: const Offset(0, 5),                ),              ],              border: Border.all(color: Colors.grey[100]!),            ),            child: Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                Container(                  padding: const EdgeInsets.all(32.0),                  decoration: BoxDecoration(                    border: Border(                      bottom: BorderSide(color: Colors.grey[100]!),                    ),                    color: Colors.blue.withOpacity(0.08),                  ),                  child: Column(                    crossAxisAlignment: CrossAxisAlignment.start,                    children: [                      Text(                        'Flutter "Hello World"',                        style: TextStyle(                          fontSize: 24.0,                          fontWeight: FontWeight.bold,                          color: Colors.grey[900],                        ),                      ),                      Padding(                        padding: const EdgeInsets.only(top: 12.0),                        child: Text(                          'This AI Studio environment is optimized for full-stack React web applications. However, I have written the native Flutter code you requested! You can copy the code below or find it in the /src/main.dart file to use in your local Flutter environment.',                          style: TextStyle(                            color: Colors.grey[600],                            height: 1.5,                          ),                        ),                      ),                    ],                  ),                ),                Container(                  color: const Color(0xFF1E1E1E),                  child: Column(                    crossAxisAlignment: CrossAxisAlignment.start,                    children: [                      Container(                        padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 12.0),                        decoration: const BoxDecoration(                          color: Color(0xFF2D2D2D),                          border: Border(                            bottom: BorderSide(color: Color(0xFF404040)),                          ),                        ),                        child: Row(                          mainAxisAlignment: MainAxisAlignment.spaceBetween,                          children: [                            Row(                              children: [                                const Icon(Icons.code_outlined, size: 16, color: Colors.blueAccent),                                const SizedBox(width: 8.0),                                Text(                                  'lib/main.dart',                                  style: TextStyle(                                    color: const Color(0xFFD4D4D4),                                    fontSize: 14.0,                                    fontFamily: 'monospace',                                  ),                                ),                              ],                            ),                            Tooltip(                              message: _copied ? 'Copied!' : 'Copy code',                              child: TextButton(                                onPressed: _copyToClipboard,                                style: TextButton.styleFrom(                                  padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 6.0),                                  backgroundColor: Colors.transparent,                                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(6.0)),                                  foregroundColor: _copied ? Colors.green[500] : const Color(0xFFD4D4D4),                                  overlayColor: MaterialStateProperty.resolveWith<Color?>(                                    (Set<MaterialState> states) {                                      if (states.contains(MaterialState.hovered)) {                                        return const Color(0xFF404040);                                      }                                      return Colors.transparent;                                    },                                  ),                                ),                                child: Row(                                  children: [                                    Icon(                                      _copied ? Icons.check : Icons.copy,                                      size: 16,                                      color: _copied ? Colors.green[500] : const Color(0xFFD4D4D4),                                    ),                                    const SizedBox(width: 6.0),                                    Text(                                      _copied ? 'Copied!' : 'Copy',                                      style: TextStyle(                                        color: _copied ? Colors.green[500] : const Color(0xFFD4D4D4),                                      ),                                    ),                                  ],                                ),                              ),                            ),                          ],                        ),                      ),                      SingleChildScrollView(                        scrollDirection: Axis.horizontal,                        child: Padding(                          padding: const EdgeInsets.all(24.0),                          child: Text(                            _flutterCode,                            style: TextStyle(                              color: const Color(0xFFD4D4D4),                              fontFamily: 'monospace',                              fontSize: 14.0,                              height: 1.5,                            ),                          ),                        ),                      ),                    ],                  ),                ),              ],            ),          ),        ),      ),    );  }}